"""Offline view of real rolling predictions, kept separate from the original demo."""
import json
from pathlib import Path


def build(folder):
    payload=(folder/'demo_data.json').read_text().replace('<','\\u003c')
    (folder/'demo.html').write_text(TEMPLATE.replace('__DATA__',payload),encoding='utf-8')


TEMPLATE='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Wikipedia Navigation · Temporal controls</title>
<style>
*{box-sizing:border-box}body{margin:0;font:15px/1.5 system-ui,sans-serif;background:#f3f7f8;color:#18313a}header{background:#123b46;color:white;padding:28px max(20px,calc((100vw - 1350px)/2))}h1{font-size:28px;margin:0}main{max-width:1400px;margin:auto;padding:20px}.card{background:white;border:1px solid #dbe5e8;border-radius:10px;padding:18px;margin-bottom:18px}.controls{display:flex;flex-wrap:wrap;gap:16px}label{display:block;font-size:12px;font-weight:bold}select,input{font:inherit;padding:8px;max-width:100%;border:1px solid #9db5bd;border-radius:5px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:7px;border-bottom:1px solid #e4ecee;text-align:left}td{overflow-wrap:anywhere}p.note,footer{font-size:12px;color:#526d76}.metric{color:#117b83;font-weight:600}h2{font-size:17px;margin:0 0 10px}@media(max-width:800px){.grid{grid-template-columns:1fr}main{padding:10px}}
</style><header><h1>Topology có giúp khi local counts chưa phân biệt được?</h1><p>Đối chiếu Markov, tie-break, fusion, PPR và CycleRank trên các tháng chưa dùng để thiết kế mô hình.</p></header>
<main><section class="card"><div class="controls"><div><label for="search">Tìm source article</label><input id="search" type="search" placeholder="Tên bài…"></div><div><label for="source">Nguồn trong panel cố định</label><select id="source"></select></div><div><label for="month">Tháng test</label><select id="month"></select></div></div><p id="scope"></p><p class="note">Đổi tháng sẽ đổi mô hình đã refit và evidence theo rolling protocol. Graph/candidates giữ snapshot 01/03/2018, induced context 8.094 nodes. Counts “—” là không quan sát được, không chứng minh zero. Score giữa các model không cùng scale; tie-break score chỉ mã hóa thứ tự.</p></section><section id="models" class="grid"></section><section class="card"><h2>Future destinations và giới hạn candidates</h2><p class="note">Tối đa 30 targets có future count cao nhất; full NDCG dùng toàn bộ labels, kể cả targets ngoài candidates. Nhãn tương lai chỉ dùng đánh giá.</p><div class="scroll"><table><thead><tr><th>Target</th><th>Candidate</th><th>Train count</th><th>Future count</th></tr></thead><tbody id="truth"></tbody></table></div></section><footer>Đây là comparative study từ aggregate counts, không user personalization hoặc online intervention. Không chọn best-test seed/model. Graph đầy đủ và null controls xem báo cáo; demo này chỉ thể hiện rolling experiment. Dữ liệu Wikimedia Clickstream CC0, WikiLinkGraphs/supporting data CC BY 4.0.</footer></main>
<script id="payload" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('payload').textContent),$=id=>document.getElementById(id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),count=x=>x?Number(x).toLocaleString('vi-VN'):'—';
const active=['M1_local','topology_tie','M6B_fusion','M3_ppr_h'];
function populate(){let prev=$('source').value,text=$('search').value.toLocaleLowerCase();const qs=data.queries.filter(q=>q.month===data.months[0]&&q.title.toLocaleLowerCase().includes(text));$('source').innerHTML=qs.map(q=>`<option value="${esc(q.id)}">${esc(q.title)}</option>`).join('');if(qs.some(q=>q.id===prev))$('source').value=prev;render()}
function render(){const q=data.queries.find(q=>q.id===$('source').value&&q.month===$('month').value);if(!q){$('models').innerHTML='<p>Không có nguồn phù hợp.</p>';$('truth').innerHTML='';$('scope').textContent='';return}
$('scope').textContent=`Train: ${q.scope.train.join(', ')} · Validation: ${q.scope.validation} · Test: ${q.month} · Candidates: ${q.candidates} · Observable future pairs: ${q.future_pairs}`;
$('models').innerHTML=active.map((m,i)=>{const p=q.models[m];return `<article class="card"><label for="model${i}">Model ${i+1}</label><select id="model${i}" data-slot="${i}">${data.models.map(x=>`<option ${x===m?'selected':''}>${esc(x)}</option>`).join('')}</select><p class="metric">Full NDCG@10: ${p.ndcg===null?'N/A':p.ndcg.toFixed(4)}</p><div class="scroll"><table><thead><tr><th>#</th><th>Destination</th><th>Train</th><th>Future</th><th>Score</th></tr></thead><tbody>${p.ranked.map((t,j)=>{const d=q.targets[t];return `<tr><td>${j+1}</td><td>${esc(d.title)}</td><td>${count(d.train)}</td><td>${count(d.future)}</td><td>${Number(p.scores[t]).toPrecision(4)}</td></tr>`}).join('')}</tbody></table></div></article>`}).join('');document.querySelectorAll('[data-slot]').forEach(el=>el.addEventListener('change',e=>{active[Number(e.target.dataset.slot)]=e.target.value;render()}));
$('truth').innerHTML=Object.entries(q.targets).filter(([t,d])=>d.future>0).sort((a,b)=>b[1].future-a[1].future).slice(0,30).map(([t,d])=>`<tr><td>${esc(d.title)}</td><td>${d.eligible?'Có':'Ngoài candidates'}</td><td>${count(d.train)}</td><td>${count(d.future)}</td></tr>`).join('')||'<tr><td colspan="4">Không có observable future labels.</td></tr>';
}
$('month').innerHTML=data.months.map(m=>`<option>${m}</option>`).join('');$('search').addEventListener('input',populate);['source','month'].forEach(id=>$(id).addEventListener('change',render));populate();
</script></html>'''
